#!/usr/bin/env python3"""vdget — Universal Video DownloaderTries yt-dlp first. If that fails, launches headless Chromium to snipethe real stream URL, then downloads it with yt-dlp.Usage:    python vdget.py <URL> [options]Options:    -q, --quality   best|1080|720|480|audio  (default: best)    -f, --format    mp4|mkv|webm|mp3         (default: mp4)    -o, --output    output directory          (default: ./downloads)    -w, --wait      seconds for browser wait  (default: 15)    --no-headless   show browser window    --cookies       path to cookies.txt    --snipe-only    skip yt-dlp, go straight to browser    --dry-run       find URL but don't download"""import argparseimport jsonimport reimport shutilimport subprocessimport sysimport timefrom pathlib import Pathfrom urllib.parse import quote# ── ANSI colors ────────────────────────────────────────────────────────────────R  = "\033[31m"G  = "\033[32m"Y  = "\033[33m"C  = "\033[36m"M  = "\033[35m"DIM = "\033[90m"B  = "\033[1m"RST = "\033[0m"# ── Stream detection patterns ──────────────────────────────────────────────────STREAM_PATTERNS = [    re.compile(r'https?://[^\s\'"<>]+\.m3u8[^\s\'"<>]*', re.I),    re.compile(r'https?://[^\s\'"<>]+\.mpd[^\s\'"<>]*', re.I),    re.compile(r'https?://[^\s\'"<>]+\.(mp4|mkv|webm|avi|mov|flv)[^\s\'"<>]*', re.I),    re.compile(r'https?://[^\s\'"<>]*/(hls|dash|stream|video|play)[^\s\'"<>]*\.(m3u8|mpd|ts|mp4|m4s)', re.I),]BLOCKLIST = re.compile(    r'(googlevideo\.com/initplayback|doubleclick|googlesyndication'    r'|analytics|facebook\.com/tr|\.jpg|\.jpeg|\.png|\.gif|\.webp'    r'|\.css|\.js(?!\w)|manifest\.json|/api/|/track|/pixel'    r'|mediareaction|/beacon|/ping|/log|/event|/telemetry'    r'|/impression|/collect|/hit)',    re.I)EMBED_HOSTS = re.compile(    r'(vsembed|cloudnestra|nestra\.com|filemoon|streamtape|voe\.sx|upstream|'    r'doodstream|mixdrop|mp4upload|vidmoly|streamlare|'    r'embedsito|playm4u|fembed|gofile|streamhub|streamsb|'    r'sbplay|rabbitstream|vidcloud|superembed|smashystream|'    r'uqload|vidoza|sendvid|streamwish|vtbe|filelions|'    r'alions|playerwish|tubeload|embedrise|ghost|guccihide|'    r'embed\.|/embed|/player|/rcp/|/e/)',    re.I,)MEDIA_RESOURCE_TYPES = {'media', 'xhr', 'fetch', 'websocket', 'other'}PLAY_SELECTORS = [    'video', '.jw-display-icon-container', '.vjs-big-play-button',    '.plyr__control--overlaid', 'button.play', '.fp-play',    '[data-testid="play"]', 'button[aria-label*="play" i]',    '[class*="play-button"]', '[class*="playBtn"]',]# ── Helpers ────────────────────────────────────────────────────────────────────def log(msg):    print(msg)def ok(msg):     print(f"{G}[✓]{RST} {msg}")def info(msg):   print(f"{C}[*]{RST} {msg}")def warn(msg):   print(f"{Y}[!]{RST} {msg}")def err(msg):    print(f"{R}[✗]{RST} {msg}")def dim(msg):    print(f"{DIM}{msg}{RST}")def find_ytdlp() -> str:    venv = Path(sys.executable).parent / "yt-dlp"    if venv.exists():        return str(venv)    found = shutil.which("yt-dlp")    if found:        return found    local = Path.home() / ".local" / "bin" / "yt-dlp"    if local.exists():        return str(local)    raise FileNotFoundError("yt-dlp not found. Run: pip install yt-dlp")def detect_type(url: str) -> str:    u = url.lower().split("?")[0]    if ".m3u8" in u: return "HLS"    if ".mpd"  in u: return "DASH"    if ".mp4"  in u: return "MP4"    if ".mkv"  in u: return "MKV"    if ".webm" in u: return "WebM"    return "stream"def build_format_sel(quality: str) -> str:    m = {        "best":  "bestvideo+bestaudio/best[acodec!=none]",        "1080":  "bestvideo[height<=1080]+bestaudio/best[height<=1080][acodec!=none]",        "720":   "bestvideo[height<=720]+bestaudio/best[height<=720][acodec!=none]",        "480":   "bestvideo[height<=480]+bestaudio/best[height<=480][acodec!=none]",        "audio": "bestaudio/best[acodec!=none]",    }    return m.get(quality, m["best"])def build_ytdlp_cmd(url: str, quality: str, fmt: str, output_dir: Path,                    referer: str = "", cookies: str = "") -> list[str]:    out = str(output_dir.resolve() / "%(title).80s.%(ext)s")    cmd = [        find_ytdlp(),        "--no-playlist",        "--merge-output-format", fmt,        "--format", build_format_sel(quality),        "--output", out,        "--fragment-retries", "15",        "--retries", "10",        "--concurrent-fragments", "1",   # avoid 429s from CDN rate limiting        "--sleep-interval", "2",         # 2s between requests        "--max-sleep-interval", "5",     # random jitter up to 5s        "--retry-sleep", "5",            # wait 5s before retrying a failed fragment        "--hls-use-mpegts",        "--windows-filenames",        "--no-part",        "--postprocessor-args", "ffmpeg:-c:a aac -c:v copy",        "--newline",        "--progress",    ]    if referer:        cmd += ["--add-header", f"Referer:{referer}"]        cmd += ["--add-header",                "User-Agent:Mozilla/5.0 (Windows NT 10.0; Win64; x64) "                "AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36"]    if cookies:        cmd += ["--cookies", cookies]    if quality == "audio":        cmd += ["--extract-audio", "--audio-format", "mp3", "--audio-quality", "0"]    cmd.append(url)    return cmd# ── Strategy 1: direct yt-dlp ──────────────────────────────────────────────────def ytdlp_probe(url: str) -> bool:    """Quick check: can yt-dlp extract this URL at all?"""    try:        r = subprocess.run(            [find_ytdlp(), "--simulate", "--no-playlist", "--quiet", url],            capture_output=True, timeout=30        )        return r.returncode == 0    except Exception:        return Falsedef ytdlp_download(url: str, quality: str, fmt: str, output_dir: Path,                   referer: str = "", cookies: str = "") -> bool:    """Run yt-dlp and stream output. Returns True on success."""    cmd = build_ytdlp_cmd(url, quality, fmt, output_dir, referer, cookies)    dim(f"$ {' '.join(cmd)}\n")    result = subprocess.run(cmd)    return result.returncode == 0# ── Strategy 2: headless browser sniper ───────────────────────────────────────def snipe(page_url: str, wait: float, headless: bool,          cookies_file: str | None) -> list[dict]:    """    Launch headless Chromium, follow embed chain, intercept stream URLs.    Returns list of {url, type, referer} dicts.    """    try:        from playwright.sync_api import sync_playwright    except ImportError:        err("playwright not installed. Run: pip install playwright && python -m playwright install chromium")        return []    found: dict[str, dict] = {}    all_requests: list[tuple] = []    def check_url(url: str, referer: str = "", source: str = ""):        clean = url if (".m3u8" in url or ".mpd" in url) else url.split("?")[0]        if BLOCKLIST.search(clean):            return        for pat in STREAM_PATTERNS:            if pat.search(clean):                if clean not in found:                    found[clean] = {"url": clean, "type": detect_type(clean), "referer": referer}                    ok(f"Stream found [{detect_type(clean)}]: {clean[:100]}")                break    def make_hooks(label: str):        def on_req(req):            all_requests.append((req.resource_type, req.url))            if req.resource_type in MEDIA_RESOURCE_TYPES:                check_url(req.url, referer=req.headers.get("referer", ""), source=label)        def on_resp(resp):            ct = resp.headers.get("content-type", "")            if any(x in ct for x in ("mpegurl", "dash+xml", "mp4", "video", "octet-stream")):                check_url(resp.url, source=label)        return on_req, on_resp    def try_click(frames):        for frame in frames:            for sel in PLAY_SELECTORS:                try:                    el = frame.query_selector(sel)                    if el and el.is_visible():                        el.click(timeout=2000)                        dim(f"  clicked {sel!r} in {frame.url[:60]}")                        return                except:                    pass    def scan_frames(frames, label):        for frame in frames:            try:                html = frame.content()                for pat in STREAM_PATTERNS:                    for m in pat.finditer(html):                        check_url(m.group(0), source=f"html:{label}")            except:                pass    def visit(context, url: str, label: str, wait_secs: float):        page = context.new_page()        on_req, on_resp = make_hooks(label)        page.on("request", on_req)        page.on("response", on_resp)        context.on("page", lambda p: (p.on("request", on_req), p.on("response", on_resp)))        info(f"Visiting [{label}]: {url[:90]}")        try:            page.goto(url, wait_until="domcontentloaded", timeout=30000)        except Exception as e:            warn(str(e)[:80])        # Wait for page JS to settle and iframes to inject        time.sleep(4)        def get_frames():            return [page] + list(page.frames)        frames = get_frames()        iframes = [f for f in frames if f.url and f.url not in ("about:blank", "", url)]        if iframes:            dim(f"  {len(iframes)} iframe(s): " + " | ".join(f.url[:60] for f in iframes[:3]))        # Attempt 1: click in all current frames        try_click(frames)        time.sleep(2)        # Attempt 2: click anywhere on the page body to dismiss overlays/ads        try:            page.mouse.click(640, 360)            time.sleep(1)        except:            pass        # Attempt 3: click video element directly via JS (works even if invisible)        try:            page.evaluate("""                const v = document.querySelector('video');                if (v) { v.play(); }            """)        except:            pass        # Re-scan frames (new iframes may have appeared after clicks)        for _ in range(3):            try:                page.wait_for_load_state("networkidle", timeout=5000)            except:                pass            time.sleep(1)        frames = get_frames()        new_iframes = [f for f in frames if f.url and f.url not in ("about:blank", "", url)]        if len(new_iframes) > len(iframes):            dim(f"  new iframe(s) appeared: " + " | ".join(f.url[:60] for f in new_iframes[:3]))            try_click(frames)        deadline = time.time() + wait_secs        while time.time() < deadline:            time.sleep(1)            frames = get_frames()            scan_frames(frames, label)            if found:                time.sleep(2)                scan_frames(frames, label)                break        page.close()    with sync_playwright() as p:        browser = p.chromium.launch(            headless=headless,            args=["--no-sandbox", "--disable-blink-features=AutomationControlled",                  "--disable-dev-shm-usage"],        )        context = browser.new_context(            user_agent=(                "Mozilla/5.0 (Windows NT 10.0; Win64; x64) "                "AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36"            ),            viewport={"width": 1280, "height": 720},            extra_http_headers={"Accept-Language": "en-US,en;q=0.9"},        )        if cookies_file:            _load_cookies(context, cookies_file)        # ── Phase 1: load main page, collect embed URLs ────────────────────        embed_urls: list[str] = []        page = context.new_page()        on_req0, on_resp0 = make_hooks("main")        def on_req_main(req):            all_requests.append((req.resource_type, req.url))            if req.resource_type in MEDIA_RESOURCE_TYPES:                check_url(req.url, referer=req.headers.get("referer", ""), source="main")            if req.resource_type == "document" and EMBED_HOSTS.search(req.url):                if req.url != page_url and req.url not in embed_urls:                    embed_urls.append(req.url)                    dim(f"  embed detected: {req.url[:90]}")        page.on("request", on_req_main)        page.on("response", on_resp0)        context.on("page", lambda p: (p.on("request", on_req_main), p.on("response", on_resp0)))        info(f"Loading main page...")        try:            page.goto(page_url, wait_until="domcontentloaded", timeout=30000)        except Exception as e:            warn(str(e)[:80])        time.sleep(4)        frames = [page] + list(page.frames)        # collect iframe URLs that match embed hosts        for fr in frames:            if fr.url and EMBED_HOSTS.search(fr.url) and fr.url not in embed_urls:                embed_urls.append(fr.url)        try_click(frames)        time.sleep(2)        scan_frames(frames, "main")        page.close()        # ── Phase 2: visit embed URLs — deepest first ────────────────────────        if not found and embed_urls:            # Reverse so we try the deepest embed (last redirect) first            ordered = list(dict.fromkeys(reversed(embed_urls)))            info(f"Following {len(ordered)} embed URL(s) (deepest first)...")            for i, eurl in enumerate(ordered):                visit(context, eurl, f"embed-{i+1}", max(wait, 15))                if found:                    break        # ── Phase 3: fallback — try remaining document requests ────────────        if not found:            seen = set(embed_urls)            docs = [u for t, u in all_requests                    if t == "document" and u != page_url                    and u not in seen                    and urlparse(page_url).netloc not in u]            if docs:                info(f"Trying {min(len(docs), 3)} fallback document URL(s)...")                for i, durl in enumerate(docs[:3]):                    visit(context, durl, f"doc-{i+1}", 15)                    if found:                        break        browser.close()    return list(found.values())def _load_cookies(context, cookies_file: str):    cookies = []    try:        with open(cookies_file) as f:            for line in f:                line = line.strip()                if not line or line.startswith("#"):                    continue                parts = line.split("\t")                if len(parts) < 7:                    continue                domain, _, path, secure, expires, name, value = parts[:7]                cookies.append({                    "name": name, "value": value,                    "domain": domain.lstrip("."), "path": path,                    "secure": secure.upper() == "TRUE",                    "expires": int(expires) if expires.isdigit() else -1,                })        context.add_cookies(cookies)        dim(f"  loaded {len(cookies)} cookies")    except Exception as e:        warn(f"Cookie load error: {e}")def urlparse(url):    from urllib.parse import urlparse as _up    return _up(url)# ── Banner ─────────────────────────────────────────────────────────────────────def banner():    print(f"""{C}  ██╗   ██╗██████╗  ██████╗ ███████╗████████╗  ██║   ██║██╔══██╗██╔════╝ ██╔════╝╚══██╔══╝  ██║   ██║██║  ██║██║  ███╗█████╗     ██║  ╚██╗ ██╔╝██║  ██║██║   ██║██╔══╝     ██║   ╚████╔╝ ██████╔╝╚██████╔╝███████╗   ██║    ╚═══╝  ╚═════╝  ╚═════╝ ╚══════╝   ╚═╝{RST}{DIM}  universal video downloader — yt-dlp + headless sniper{RST}""")# ── Main ───────────────────────────────────────────────────────────────────────def main():    parser = argparse.ArgumentParser(        prog="vdget",        description="Universal video downloader. Tries yt-dlp first, falls back to headless browser sniper.",        formatter_class=argparse.RawDescriptionHelpFormatter,        epilog="""examples:  python vdget.py https://youtube.com/watch?v=xxx  python vdget.py https://flixmomo.tv/movie/xxx -q 1080  python vdget.py https://somesite.com/video -q audio -f mp3  python vdget.py https://site.com/video --snipe-only --no-headless  python vdget.py https://site.com/video --cookies cookies.txt"""    )    parser.add_argument("url",                    help="URL to download")    parser.add_argument("-q", "--quality",        default="best",                        choices=["best", "1080", "720", "480", "audio"])    parser.add_argument("-f", "--format",         default="mp4",                        choices=["mp4", "mkv", "webm", "mp3"])    parser.add_argument("-o", "--output",         default="./downloads",                        help="Output directory (default: ./downloads)")    parser.add_argument("-w", "--wait",           type=float, default=15,                        help="Seconds to wait for stream in browser (default: 15)")    parser.add_argument("--no-headless",          action="store_true",                        help="Show browser window")    parser.add_argument("--cookies",              metavar="FILE",                        help="Netscape cookies.txt")    parser.add_argument("--snipe-only",           action="store_true",                        help="Skip yt-dlp, go straight to browser sniper")    parser.add_argument("--dry-run",              action="store_true",                        help="Find stream URL but don't download")    args = parser.parse_args()    banner()    output_dir = Path(args.output).resolve()    output_dir.mkdir(parents=True, exist_ok=True)    print(f"{B}URL{RST}     {args.url}")    print(f"{B}QUALITY{RST} {args.quality}  {B}FORMAT{RST} {args.format}  {B}OUTPUT{RST} {args.output}")    print(f"{DIM}{'─' * 60}{RST}\n")    # ── Strategy 1: try yt-dlp directly ───────────────────────────────────────    if not args.snipe_only:        info("Trying yt-dlp directly...")        if ytdlp_probe(args.url):            ok("yt-dlp can handle this URL")            if args.dry_run:                ok("dry-run: skipping download")                sys.exit(0)            success = ytdlp_download(                args.url, args.quality, args.format,                output_dir, cookies=args.cookies or ""            )            if success:                print()                ok(f"Done! Saved to: {output_dir}/")                sys.exit(0)            else:                warn("yt-dlp failed — falling back to browser sniper...")        else:            warn("yt-dlp cannot extract this URL — switching to browser sniper...")    # ── Strategy 2: headless browser sniper ───────────────────────────────────    print()    info("Launching headless browser...")    streams = snipe(        page_url=args.url,        wait=args.wait,        headless=not args.no_headless,        cookies_file=args.cookies,    )    if not streams:        print()        err("No streams found.")        print(f"  Try: {Y}--wait 30{RST}  |  {Y}--no-headless{RST}  |  {Y}--cookies cookies.txt{RST}")        sys.exit(1)    # Pick best stream: HLS > DASH > MP4 > other    priority = {"HLS": 0, "DASH": 1, "MP4": 2, "MKV": 3, "WebM": 4, "stream": 5}    best = min(streams, key=lambda s: priority.get(s["type"], 99))    print()    ok(f"Best stream: [{best['type']}] {best['url'][:100]}")    if args.dry_run:        print(f"\n{DIM}dry-run: skipping download{RST}")        if len(streams) > 1:            print(f"\n{DIM}Other streams found:{RST}")            for s in streams:                print(f"  [{s['type']}] {s['url'][:100]}")        sys.exit(0)    # Download the sniped stream via yt-dlp    print()    info("Downloading sniped stream via yt-dlp...")    success = ytdlp_download(        best["url"], args.quality, args.format,        output_dir,        referer=best.get("referer") or args.url,        cookies=args.cookies or "",    )    if success:        print()        ok(f"Done! Saved to: {output_dir}/")    else:        err("Download failed.")        if len(streams) > 1:            warn("Other streams available — try --dry-run to inspect them manually")        sys.exit(1)if __name__ == "__main__":    main()